\documentclass{beamer}
\usetheme{Madrid}
\title{Traffic Calming for the Elm Street Corridor}
\author{Neighbourhood Council --- Transportation Committee}
\date{May 2026}
\begin{document}

\begin{frame}
\titlepage
\end{frame}

\begin{frame}{Why We Are Here}
\begin{itemize}
\item speeds above 40 km/h, the top complaint from residents
\item two cyclist collisions in 2025, both at dusk
\item the school route crosses Elm Street at three unsignalised points
\end{itemize}
\end{frame}

\begin{frame}{Proposed Measures}
\begin{itemize}
\item speed cushions on the 200 and 300 blocks
\item a raised crosswalk at the school entrance, built in summer 2026
\item curb extensions at the Elm and Maple junction
\end{itemize}
\end{frame}

\begin{frame}{Costs and Funding}
\begin{itemize}
\item total estimate about 180,000 dollars, cushions the cheapest item
\item 60\% covered by the municipal road-safety grant
\item the remainder from the ward discretionary budget
\end{itemize}
\end{frame}

\begin{frame}{Timeline}
\begin{itemize}
\item consultation closes on 30 June
\item detailed design in August, tender in October
\item construction from April to June 2027
\end{itemize}
\end{frame}

\begin{frame}{Discussion}
Questions and comments from the floor.
\end{frame}

\end{document}
